class Solution {
public:
    vector<vector<string>> displayTable(vector<vector<string>>& orders) {
        set<string> foods;
        map<int, map<string, int>> tables;
        for (const auto& order : orders) {
            foods.insert(order[2]);
            ++tables[stoi(order[1])][order[2]];
        }
        vector<vector<string>> result;
        vector<string> header = {"Table"};
        for (const string& food : foods) header.push_back(food);
        result.push_back(header);
        for (const auto& table : tables) {
            vector<string> row = {to_string(table.first)};
            for (const string& food : foods) {
                auto it = table.second.find(food);
                row.push_back(to_string(it == table.second.end() ? 0 : it->second));
            }
            result.push_back(row);
        }
        return result;
    }
};
